   620  _dwarf_debuglink_finder_newpath(
   621      char         * path_in,
   622      unsigned char *crc_in,
   623      unsigned       buildid_len_in,
   624      unsigned char *buildid_in,
   625      dwarfstring    *m,
   626      int * fd_out)
   627  {
   628      unsigned char  lcrc[4];
   629      char          *debuglinkpath = 0; /* must be freed */
   630      unsigned char *crc = 0;
   631      char          *debuglinkfullpath = 0;
   632      unsigned       debuglinkfullpath_strlen = 0;
   633      unsigned       buildid_type = 0;
   634      char         * buildidownername = 0;
   635      unsigned char *buildid = 0;
   636      unsigned       buildid_length = 0;
   637      char        ** paths = 0; /* must be freed */
   638      unsigned       paths_count = 0;
   639      Dwarf_Debug dbg = 0;
   640      Dwarf_Error error = 0;
   641      char *path = path_in;
   642      Dwarf_Bool didmatch = FALSE;
   643      int res = 0;
   644
   645      res = dwarf_init_path(path,
   646          0,0,
   647          DW_GROUPNUMBER_ANY,
   648          0,0, &dbg,&error);
   649      if (res == DW_DLV_ERROR) {
   650          /* ASSERT:  dbg is NULL as init failed */
   651          dwarf_dealloc_error(dbg,error);
   652          error = 0;
   653          return DW_DLV_NO_ENTRY;
   654      }
   655      if (res == DW_DLV_NO_ENTRY) {
   656          /* should never happen */
   657          return DW_DLV_NO_ENTRY;
   658      }
   659      res = dwarf_gnu_debuglink(dbg,
   660          &debuglinkpath,
   661          &crc, &debuglinkfullpath, &debuglinkfullpath_strlen,
   662          &buildid_type, &buildidownername,
   663          &buildid, &buildid_length,
   664          &paths, &paths_count, &error);
   665      if (res == DW_DLV_ERROR) {
   666          dwarf_dealloc_error(dbg,error);
   667          dwarf_finish(dbg);
   668          error = 0;
   669          dbg = 0;
   670          return DW_DLV_NO_ENTRY;
   671      }
   672      if (res == DW_DLV_NO_ENTRY) {
   673          /*  There is no debuglink section */
   674          dwarf_finish(dbg);
   675          dbg = 0;
   676          return DW_DLV_NO_ENTRY;
   677      }
   678      free(paths);
   679      paths = 0;
   680
   681      memset(&lcrc[0],0,sizeof(lcrc));
   682      if (crc_in && !crc) {
   683          int res1 = 0;
   684          res1 = dwarf_crc32(dbg,lcrc,&error);
   685          if (res1 == DW_DLV_ERROR) {
   686              paths = 0;
   687              free(debuglinkfullpath);
   688              dwarf_dealloc_error(dbg,error);
   689              dwarf_finish(dbg);
   690              error = 0;
   691              dbg = 0;
   692              /*  Cannot match the crc_in, give up. */
   693              return DW_DLV_NO_ENTRY;
   694          }
   695          if (res1 == DW_DLV_OK) {
   696              crc = &lcrc[0];
   697          }
   698      }
   699      free(debuglinkfullpath);
   700      didmatch = match_buildid(
   701          /* This is about the executable */
   702          crc_in,buildid_len_in,buildid_in,
   703          /* pass in local so we can calculate the missing crc */
   704          /* following is the target, ie, debug */
   705          crc,buildid_length,buildid);
   706      if (error) {
   707          /*  This should never happen. It would mean
   708              error was set without DW_DLV_ERROR */
   709          dwarf_dealloc_error(dbg,error);
   710          error = 0;
   711      }
   712      if (didmatch) {
   713          dwarfstring_append(m,path);
   714          *fd_out = dbg->de_fd;
   715          dbg->de_owns_fd = FALSE;
   716          dwarf_finish(dbg);
   717          dbg = 0;
   718          return DW_DLV_OK;
   719      }
   720      dwarf_finish(dbg);
   721      return DW_DLV_NO_ENTRY;
   722  }
